/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    InventItemSalesSetup    InventItemSalesSetup;
    InventItemInventSetup   InventItemInventSetup;

    delete_from InventItemSalesSetup where InventItemSalesSetup.ItemId == 'CT-16-TOBACCO' && InventItemSalesSetup.InventDimid == '#0000000150003D90';
    delete_from InventItemInventSetup where InventItemInventSetup.ItemId == 'CT-16-TOBACCO' && InventItemInventSetup.InventDimid == '#0000000150003D90';

    info('Done');
}
